WITH metrics AS (SELECT id, dept_name, location, budget, AVG(budget) OVER w_ordered running_avg_budget, MIN(budget) OVER w_ordered running_min_budget, COUNT(budget) OVER w_ordered running_count_budget FROM departments WINDOW w_ordered AS (PARTITION BY location, dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN running_min_budget >= 4118000 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_min_budget_tier, CASE WHEN budget >= 3227000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, COUNT(CASE WHEN dept_name = 'Legal' THEN 1 END) AS legal_count, ROUND(SUM(running_avg_budget) / NULLIF(COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END), 0), 2) AS running_avg_budget_per_chiang_mai, COUNT(*) AS cnt, MAX(budget) FILTER (WHERE dept_name = 'Finance') AS finance_max_budget, AVG(budget) FILTER (WHERE location = 'Tokyo') AS tokyo_avg_budget FROM metrics GROUP BY 1, 2 ORDER BY finance_max_budget NULLS LAST;
